/**
 * PPDO Portal — service worker (PWA Phase 1).
 *
 * Hand-written rather than generated by next-pwa/Serwist. Rationale in
 * docs/PWA_Feasibility_Study.md §6.1: `next.config.mjs` has no custom webpack
 * config at all, so adding a build plugin would be a bigger change to this repo
 * than the ~120 lines it generates — and because everything under
 * /_next/static/ is content-hashed, runtime cache-first needs no precache
 * manifest to be safe.
 *
 * WHAT THIS CACHES
 *   /_next/static/*, /icons/*, /images/*, /favicon.ico  → cache-first, immutable
 *   navigations (HTML)                                  → network-first, cache fallback,
 *                                                         then the offline page
 *
 * WHAT THIS DELIBERATELY NEVER TOUCHES — see study §6.2
 *   The API. In production it lives on a different origin
 *   (ppdo-portal-api-*.azurewebsites.net), so the same-origin guard below
 *   already excludes it; the explicit /api/ check covers local dev via the SWA
 *   CLI, where the API is proxied same-origin at :4280.
 *
 *   This is not an oversight. Caching API responses would write provincial
 *   budget figures, purchase requests and personnel data into Cache Storage as
 *   plaintext — readable by any script on the origin, surviving logout, on
 *   machines that in a provincial office are frequently shared. The app
 *   deliberately refuses to put even the access token in localStorage
 *   (see src/lib/auth.ts); caching the data it protects would be worse.
 *
 *   Offline *data* is study §11 (offline AIP authoring) and is a separate,
 *   much larger piece of work with its own security decision attached.
 *
 * CACHE VERSION
 *   Bump CACHE_VERSION only when this file's caching STRATEGY changes — not on
 *   every release. Static assets are content-hashed, so a new deploy simply
 *   requests new URLs; tying the cache name to APP_VERSION would evict a
 *   perfectly valid cache on every patch and reintroduce the version-drift
 *   problem RAL-234 just removed.
 */

const CACHE_VERSION = "1";
const STATIC_CACHE = `ppdo-static-v${CACHE_VERSION}`;
const PAGES_CACHE = `ppdo-pages-v${CACHE_VERSION}`;
const EXPECTED_CACHES = [STATIC_CACHE, PAGES_CACHE];

const OFFLINE_URL = "/offline.html";

// Kept tiny on purpose. Precaching the whole 4.3 MB build would download the
// entire app on install over a provincial mobile connection, most of which the
// user will never open (study §3.1). Everything else is cached as it is used.
const PRECACHE_URLS = [OFFLINE_URL, "/icons/icon-192.png"];

// Content-hashed filenames accumulate across deploys — old chunks are never
// requested again but would sit in the cache forever. Trimmed on activate.
const MAX_STATIC_ENTRIES = 300;

const STATIC_PREFIXES = ["/_next/static/", "/icons/", "/images/"];
const STATIC_EXACT = ["/favicon.ico"];

function isStaticAsset(pathname) {
  return (
    STATIC_PREFIXES.some((prefix) => pathname.startsWith(prefix)) ||
    STATIC_EXACT.includes(pathname)
  );
}

// ── Install ────────────────────────────────────────────────────────────────
// No skipWaiting() here: a new worker must not swap assets under a page the
// user is already working in. It waits, the page notices and offers to reload,
// and only then does the SKIP_WAITING message below activate it.

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) => cache.addAll(PRECACHE_URLS))
  );
});

// ── Activate ───────────────────────────────────────────────────────────────

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith("ppdo-") && !EXPECTED_CACHES.includes(name))
          .map((name) => caches.delete(name))
      );

      // Trim the static cache. Entries are immutable and content-addressed, so
      // dropping an excess one is harmless — it is simply re-fetched if needed.
      const cache = await caches.open(STATIC_CACHE);
      const keys = await cache.keys();
      if (keys.length > MAX_STATIC_ENTRIES) {
        await Promise.all(
          keys.slice(0, keys.length - MAX_STATIC_ENTRIES).map((key) => cache.delete(key))
        );
      }

      await self.clients.claim();
    })()
  );
});

// ── Update handshake ───────────────────────────────────────────────────────

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

// ── Fetch ──────────────────────────────────────────────────────────────────

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Never interfere with writes, or with anything that isn't a plain GET.
  if (request.method !== "GET") return;

  let url;
  try {
    url = new URL(request.url);
  } catch {
    return;
  }

  // Cross-origin (the API in production, fonts, anything else) — leave alone.
  if (url.origin !== self.location.origin) return;

  // Same-origin API, i.e. local dev behind the SWA CLI proxy. Never cached.
  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (isStaticAsset(url.pathname)) {
    event.respondWith(handleStaticAsset(request));
  }
});

/**
 * Navigations: network-first. HTML filenames are NOT content-hashed, so serving
 * a cached page first would pin the user to an old build until the cache was
 * cleared. Falls back to the cached copy, then to the offline page.
 */
async function handleNavigation(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(PAGES_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;

    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;

    return new Response("You are offline.", {
      status: 503,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  }
}

/**
 * Static assets: cache-first, safe because these URLs are content-hashed —
 * a given URL's bytes never change, so a hit can never be stale.
 */
async function handleStaticAsset(request) {
  const cached = await caches.match(request);
  if (cached) return cached;

  try {
    const response = await fetch(request);
    // Only store real successes. An opaque or error response cached here would
    // be served back indefinitely as if it were the asset.
    if (response && response.ok && response.type === "basic") {
      const cache = await caches.open(STATIC_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    // Nothing cached and no network — let the browser surface its own error.
    throw err;
  }
}
